import base64

files = {
    'js/brief.js': {
        'b64': '''''',
        'sha': 'f5218c1c1b2f67946588de7b835c14b4f657f217'
    }
}

for filepath, data in files.items():
    decoded = base64.b64decode(data['b64'])
    with open(filepath, 'wb') as f:
        f.write(decoded)
    print(f"Restored {filepath}")

